mapper.select:
select source, channel, activity_id, activity_type, sku_id, stock_count
from sc_sku_activity
where source = #{source}
  and channel = #{channel}
  and sku_id = #{goodsId}
  and activity_type = 'seckill'
limit 1

mapper.update:
update sc_sku_activity
set stock_count = stock_count - 1
where activity_id = #{activityId}
  and sku_id = #{goodsId}
  and activity_type = 'seckill'
  and stock_count > 0

update sc_sku_activity
set stock_count = stock_count + 1
where activity_id = #{activityId}
  and sku_id = #{goodsId}
  and activity_type = 'seckill'
